L31_1 = {}
L31_1.m_CutScenKey_Talk = "WINTERVACATION_ACT2_INTERLUDE3@31#Talk"
L31_1.m_CutScenProcessKey = 31
L31_1.m_CutScenID = 7300201
L31_1.m_CutScenStrID = "WINTERVACATION_ACT2_INTERLUDE3"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_HATE"
L31_1.m_CharStrID = "YUMI_POLICE_NULL_NULL"
L31_1.m_Pos = "C"
L31_1.m_Talk_KOREA = "말도 안돼. 고작 30분만에, 똑같은 사건이, 전혀 다른 장소에서 세 번씩이나 일어났다고?"
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "嘘。たった30分の間に同じ事件がまったく違う場所で3回も起こったの？"
L31_1.m_Talk_ENG = "That's impossible. Are you saying the same incident happened three times in completely different locations in just thirty minutes?"
L31_1.m_Talk_TWN = "怎麼可能？短短30分鐘內，同樣的事件竟然在完全不同的地方發生了三次？"
L31_1.m_Talk_SCN = "怎么可能？短短30分钟内，同样的事件竟然在完全不同的地方发生了三次？"
L31_1.m_Talk_DEU = "That's impossible. Are you saying the same incident happened three times in completely different locations in just thirty minutes?"
L31_1.m_Talk_FRA = "That's impossible. Are you saying the same incident happened three times in completely different locations in just thirty minutes?"
L32_1 = {}
L32_1.m_CutScenKey_Talk = "WINTERVACATION_ACT2_INTERLUDE3@32#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 7300201
L32_1.m_CutScenStrID = "WINTERVACATION_ACT2_INTERLUDE3"
