L32_1.m_Pos = "C"
L32_1.m_Crash = 30
L32_1.m_Talk_KOREA = "한 사람이 그 먼 거리를 오가며 범죄를 저지르는 건 불가능해. 그건 강소영 경위가 차를 몰아도 안 된다고!"
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "1人がこの離れた距離を行き来しながら犯罪を犯すのは不可能よ。マエカワ警部補の運転でも無理なのに！"
L32_1.m_Talk_ENG = "There's no way one person could commit crimes over such a large distance. Even you, Lieutenant Kang, wouldn't be able to do that by driving!"
L32_1.m_Talk_TWN = "一個人不可能往返這麼遠來回作案，即使是姜素英警官開車也辦不到！"
L32_1.m_Talk_SCN = "一个人不可能往返这么远来回作案，即使是樱井爱理警官开车也做不到！"
L32_1.m_Talk_DEU = "There's no way one person could commit crimes over such a large distance. Even you, Lieutenant Kang, wouldn't be able to do that by driving!"
L32_1.m_Talk_FRA = "There's no way one person could commit crimes over such a large distance. Even you, Lieutenant Kang, wouldn't be able to do that by driving!"
