L43_1 = "KAMEN_NPC_TV_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "<color=#ffd34c>어린이</color> 여러분의 도움이 없었다면 사악한 백작의 음모를 막지 못했겠지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "<color=#ffd34c>子ども</color>のみんなの応援がなかったら邪悪な伯爵の企みは阻止できなかったはずだ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Without the help of all you <color=#ffd34c>children</color>, we wouldn't have been able to stop the evil Count's plot."
L42_1.m_Talk_ENG = L43_1
L43_1 = "[小朋友] 如果沒有你們的幫助，我們就無法阻止邪惡伯爵的陰謀。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "[小朋友] 如果没有你们的帮助，我们就无法阻止邪恶伯爵的阴谋。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Without the help of all you <color=#ffd34c>children</color>, we wouldn't have been able to stop the evil Count's plot."
