L48_1.m_CharStrID = L49_1
L49_1 = "그래도 즐거웠지? 솔로베는 어른이 아니라 어린이니까."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "m_ImageName"
L50_1 = "ANIV2_03"
L48_1[L49_1] = L50_1
L49_1 = "でも楽しかっただろ？　ソロベーは大人じゃなくて子どもだから。"
