L49_1 = "But you still had fun, right? Since you're not an adult, but a child, Solovey."
L48_1.m_Talk_ENG = L49_1
L49_1 = "不過還是很開心吧？蘇羅薇是小孩子，不是大人嘛。"
L48_1.m_Talk_TWN = L49_1
