L50_1.m_CharStrID = L51_1
L51_1 = "왜 아닌 척하는 거야? 그냥 어른이 되길 관두면 이렇고 저런 것들을 마음껏 즐겨도 잘못이 아니라구?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "m_ImageName"
L52_1 = "ANIV2_03"
L50_1[L51_1] = L52_1
L51_1 = "なんで知ってるふりするんだよ？　大人になることを諦めればこんなことやあんなことを思う存分楽しんでもいいんだよ？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Why are you denying it? If you give up on becoming an adult, it's not wrong to enjoy things like this freely!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "為什麼要否認呢？要是不想長大，想盡情享受各種樂趣，也沒什麼不對吧？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "为什么要否认呢？要是不想长大，想尽情享受各种乐趣，也没什么不对吧？"
L50_1.m_Talk_SCN = L51_1
