L21_1 = "OLIVIE_COFFIN_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "떨어진 운석의 정체가 바이러스 형태의 침식체라니. 그거 참 흥미로운 가설이네요."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "落ちた隕石の正体がウイルス型の侵食体とは。とても興味深い仮説です。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "So the meteorite was a C.O. in the form of a virus! That's quite an interesting hypothesis."
L20_1.m_Talk_ENG = L21_1
L21_1 = "墜落的隕石竟然是病毒形態的侵蝕體。這真是個有趣的假設呢。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "坠落的陨石竟然是病毒形态的侵蚀体。这真是个有趣的假设呢。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "So the meteorite was a C.O. in the form of a virus! That's quite an interesting hypothesis."
L20_1.m_Talk_DEU = L21_1
L21_1 = "So the meteorite was a C.O. in the form of a virus! That's quite an interesting hypothesis."
L20_1.m_Talk_FRA = L21_1
