L22_1 = "WINTERVACATION_ACT2_INTERLUDE3@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 7300201
L21_1.m_CutScenStrID = "WINTERVACATION_ACT2_INTERLUDE3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "LONELY_NPC_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "가설이 아닙니다. 추락 현장에서 침식 성질을 띤 독소를 발견했거든요."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "仮説ではありません。落下現場で侵食性質を持つ毒素を発見しました。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "It's not a hypothesis. We found a toxin with Corruption properties at the crash site."
L21_1.m_Talk_ENG = L22_1
L22_1 = "這不是假設。在墜落現場發現了具有侵蝕性質的毒素。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "这不是假设。在坠落现场发现了具有侵蚀性质的毒素。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "It's not a hypothesis. We found a toxin with Corruption properties at the crash site."
L21_1.m_Talk_DEU = L22_1
L22_1 = "It's not a hypothesis. We found a toxin with Corruption properties at the crash site."
L21_1.m_Talk_FRA = L22_1
