L23_1 = "WINTERVACATION_ACT2_INTERLUDE3@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 7300201
