L23_1 = "LONELY_NPC_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "건물을 덮고 있던 거대한 줄기 식물에 붙어 기생하고 있었어요. 운석의 일부가 그곳에 남아 있던 거죠."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "建物を覆っていた巨大な蔓植物にくっついて寄生していました。隕石の一部がそこに残っていたのです。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "It was parasitizing on the massive vine plant that covered the building. A part of the meteorite was left there."
L22_1.m_Talk_ENG = L23_1
L23_1 = "附著在覆蓋建築物的巨大藤蔓植物上寄生。隕石的一部分留在那裡了。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "附着在覆盖建筑物的巨大藤蔓植物上寄生。陨石的一部分留在那里了。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "It was parasitizing on the massive vine plant that covered the building. A part of the meteorite was left there."
L22_1.m_Talk_DEU = L23_1
L23_1 = "It was parasitizing on the massive vine plant that covered the building. A part of the meteorite was left there."
