L24_1 = "OLIVIE_COFFIN_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "그런 걸 가설이라고 한답니다. 애초에 그 침식 독소가 운석에서 나왔다는 근거가 빈약하잖아요?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "そういうのを仮説と言うんです。そもそもその侵食毒素が隕石から出たという根拠が薄いでしょう？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "That's what a hypothesis is. There's no evidence that the Corruption toxin came from the meteorite in the first place, right?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "那種東西叫做假說。最初就沒有證據表明那種侵蝕毒素是從隕石中出來的，不是嗎？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "那种东西叫做假说。最初就没有证据表明那种侵蚀毒素是从陨石中出来的，不是吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "That's what a hypothesis is. There's no evidence that the Corruption toxin came from the meteorite in the first place, right?"
