L28_1 = "침식체를 생명체와 별개로 분류하는 엉터리 학자가 학계의 존중을 받고 있다니 말이야."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "侵食体と生命体を別のものとして分類するでたらめな学者が学界から尊敬されているなんてね。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "It's ridiculous that a so-called scholar, who classifies C.O.s separately from living creatures, is being respected in academia!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "把侵蝕體與生命體分門別類的胡說八道學者，竟然在學界受到尊重！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "把侵蚀体与生命体分开分类的胡说八道的学者竟然在学界受到了尊重！"
