L29_1 = "살아있다라고 정의할 수 없는 존재를 멋대로 생명체라 규정 짓는 그쪽이 문제 아닐까요?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "生きていると定義できない存在を勝手に生命体だと決めつけるそちらこそ問題があるでしょう？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Isn't the real problem you? You are arbitrarily defining something as a living creature when it can't even be considered alive."
L28_1.m_Talk_ENG = L29_1
L29_1 = "隨意將無法定義為活著的存在規定為生命體，這不是你的問題嗎？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "随意将无法定义为活着的存在规定为生命体，这不是你的问题吗？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Isn't the real problem you? You are arbitrarily defining something as a living creature when it can't even be considered alive."
