L30_1 = "듣자 하니 감옥에 가기 전엔 초콜릿도 길들이려 했다던데. 그런 열린 사고방식은 저도 존중해야겠어요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "聞いた話によれば、監獄に入る前はチョコレートも手懐けようとしたそうね。そういう水平思考は私も尊重します。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I heard that you even tried to tame a chocolate before ending up in prison. I guess I should respect that kind of open-mindedness."
L29_1.m_Talk_ENG = L30_1
L30_1 = "聽說你在進監獄之前還試圖馴服巧克力，這樣的開放思考模式我也得尊重一下。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "听说你在进监狱之前还试图驯服巧克力。这样的开放思维我也得尊重一下。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "I heard that you even tried to tame a chocolate before ending up in prison. I guess I should respect that kind of open-mindedness."
