L31_1 = "침식체는 살아있어! 유기질로 이뤄져 있지 않다고 해서 무생물이라 판단하는 그 틀에 박힌 태도가 글러 먹은 거라고!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "侵食体は生きている！　有機質で構成されていないという理由だけで無生物と判断するその頑固な態度がダメなんだ！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "C.O.s are alive! The narrow-minded attitude that they aren't living entities because they aren't made of organic material is what's wrong!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "侵蝕體是活的！不要因為它不是由有機物質構成的就判斷它沒有生命，這種刻板的態度是錯誤的！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "侵蚀体是活的！不要因为它不是由有机物质构成的就判断它没有生命，这种刻板的态度是错误的！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "C.O.s are alive! The narrow-minded attitude that they aren't living entities because they aren't made of organic material is what's wrong!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "C.O.s are alive! The narrow-minded attitude that they aren't living entities because they aren't made of organic material is what's wrong!"
