L33_1 = "저희는 논쟁이 아니라 도시관리국에 현재 상황의 위험성을 알리려고 모인 거잖아요?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "私たちは口喧嘩をするためではなく都市管理局に現在状況の危険性を知らせるために集まったんですよ？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "We're not here to argue but to inform the City Management about the dangers of the current situation, right?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "我們不是來爭論的，而是要告知城市管理局當前情況的危險性，不是嗎？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "我们不是来争论的，而是要告知城市管理局当前情况的危险性，不是吗？"
