L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "운석이 평범한 돌이 아니라는 점엔 두 분 다 동의하실 것 같네요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "隕石が普通の石ではないという点には2人とも同意してくださるっすね。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I'm sure both of you would agree that the meteorite isn't just an ordinary rock."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你們兩位應該都同意隕石不是普通的石頭吧。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "你们两位应该都同意陨石不是普通的石头吧。"
