L36_1 = "LEEYOONJUNG_COFFIN_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "그 운석이 사람 모습으로 도시를 돌아다니며 피해자를 늘리고 있단 소식도 알고 계실 테고요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "その隕石が人の姿で都市を歩き回っていて、被害者が増えているというニュースも聞いていると思うっす。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "You must also be aware that the meteorite has been walking around the city in human form, causing more victims."
L35_1.m_Talk_ENG = L36_1
L36_1 = "那顆隕石變成人形在城市裡四處遊蕩，受害者不斷增加的消息你也知道吧。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "那颗陨石变成人形在城市里四处游荡，受害者不断增加的消息你也知道吧。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "You must also be aware that the meteorite has been walking around the city in human form, causing more victims."
