L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "확실히, 일반적인 침식체라면 각기 다른 장소를 그렇게 단시간에 오가는 건 불가능하겠죠."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "確かに、普通の侵食体では異なる場所をこれほど瞬時に行き来することは不可能です。"
L38_1.m_Talk_JPN = L39_1
