L21_1.m_fTalkTime = 0.03
L22_1 = "わからなくてもいいです。教わればいいから。みんな誰かに教えてもらう前はわからないものです。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "It's okay if you don't understand. You can learn. Everyone doesn't understand things until someone teaches them."
L21_1.m_Talk_ENG = L22_1
L22_1 = "不知道也沒關係，學就好了。大家在有人教之前都是不知道的。"
