L23_1 = "실은 저도 이곳에 오면 금방 어른이 될 줄 알았는데, 아직도 방법을 잘 모르겠어요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "実は私もここに来たらすぐ大人になれると思ったのに、未だに方法がわかりません。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Actually, I thought I'd become an adult as soon as I got here, but I still don't really know how."
L22_1.m_Talk_ENG = L23_1
L23_1 = "其實我也以為來到這裡後很快就能長大成人，但我還是不知道該怎麼做。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "其实我也以为来到这里后很快就能长大成人，但我还是不知道该怎么做。"
