L18_1 = "명중은 얼어 죽을! 그게 사람을 치고 할 소리야? 살아있는 지부터 확인해!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "何が命中よ！　それが人を轢いといて言うセリフ？　生きているか確認して！"
L17_1.m_Talk_JPN = L18_1
